// spec: .qa/e2e/specs/history.md (5.1–5.3) · case: .qa/tests/history/HIST-005.md
// seed: tests/seed.user.spec.ts
// Только чтение: открывает существующие сеансы из истории, новых сеансов не создаёт.
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();

// Вид сеанса → запись в списке «היסטוריה» (берётся первая подходящая — самая свежая).
const CASES = [
  { title: 'сеанс со сбоем', row: /· (כשל אחד|\d+ כשלים)$/ },
  { title: 'спокойный сеанс без событий', row: /· בלי אירועים$/ },
  { title: 'сеанс с тревогами', row: /· (התרעה אחת|\d+ התרעות)$/ },
];

test.describe('История — детали сеанса: число событий у «מה קרה»', () => {
  for (const c of CASES) {
    test(`Детали из истории (${c.title}): рядом с «מה קרה» — «N אירועים», N = числу строк событий, нет «בלי התרעות» #92d9fdd3 @iphone @prod-safe`, async ({ page }) => {
      // 1. «היסטוריה» → первая запись нужного вида → детали
      await page.goto('/history');
      const row = page.getByRole('button', { name: c.row }).filter({ visible: true }).first();
      await expect(row).toBeVisible();
      await row.click();
      await expect(page).toHaveURL(/\/history\/.+/);

      // 2. Заголовок «מה קרה» и подпись рядом с ним
      const heading = page.getByRole('heading', { name: 'מה קרה', exact: true }).filter({ visible: true });
      await expect(heading).toBeVisible();
      const header = heading.locator('xpath=..');
      await expect(header).toHaveText(/מה קרה\s*(\d+ אירועים|אירוע אחד)/);
      const headerText = clean(await header.innerText());
      expect(headerText, 'нет «בלי התרעות» у «מה קרה»').not.toContain('בלי התרעות');
      const m = headerText.match(/(\d+) אירועים|אירוע אחד/)!;
      const n = m[1] ? Number(m[1]) : 1;

      // 3. Строки событий под «מה קרה»: столько же, у каждой время
      const rows = header.locator('xpath=following-sibling::div[1]/div');
      await expect(rows, `«${headerText}» = числу строк событий`).toHaveCount(n);
      for (const t of await rows.allInnerTexts()) expect(clean(t), 'время у события').toMatch(/\d{1,2}:\d{2}$/);
      expect(n, 'как минимум начало и конец сеанса').toBeGreaterThanOrEqual(2);
    });
  }
});
